  plan.rename.forEach(({p, name, address}) => { lines.push({prop:name, pid:p.id, what:`renamed from "${p.name}"`}); p.name = name; p.address = address; });
  plan.portfolio.forEach(({p, portfolio}) => { p.portfolio = portfolio; });
