    const c = mdCleanName(u, mp), l = (S.md.leases || []).find(z => z.unitId === u.id && !z.ended);
    const rent = l && l.rent ? l.rent : u.marketRent || null, pct = mp ? mdFeeGuess(mp.id, rent) : null;
